import sys; sys.path.insert(0,'/tmp/probe')
import png, json
def load_ink(path):
    w,h,ch,ct,px,chunks = png.load(path)
    ink=set()
    for y in range(h):
        row=y*w
        for x in range(w):
            p=px[(row+x)*ch:(row+x)*ch+3]
            if p[:3]!=b'\xff\xff\xff': ink.add((x,y))
    return w,h,ink
w,h,ink=load_ink(sys.argv[1])
scale=int(sys.argv[2])
cw,chh=10*scale,14*scale
bx,by=2*cw,2*chh
chars=''.join(chr(c) for c in range(32,127))
out={}
for i,c in enumerate(chars):
    y0,y1=by+i*chh, by+(i+1)*chh
    pts=[(x,y) for (x,y) in ink if y0<=y<y1 and x>=bx-20]
    if not pts:
        out[c]=None; continue
    xs=[p[0] for p in pts]
    # cluster into 5 glyphs by x gaps
    xs_s=sorted(set(xs))
    clusters=[]; start=xs_s[0]; prev=xs_s[0]
    for x in xs_s[1:]:
        if x>prev+1:
            clusters.append((start,prev)); start=x
        prev=x
    clusters.append((start,prev))
    ys=[p[1] for p in pts]
    out[c]=dict(clusters=clusters, ymin=min(ys)-y0, ymax=max(ys)-y0, cell_y0=y0)
json.dump(out, open(sys.argv[3],'w'))
for c in chars:
    o=out[c]
    if o is None: print(repr(c),"NO INK")
    else: print(repr(c), o['clusters'], "y",o['ymin'],o['ymax'])
